--- /dev/null
+++ b/src/db/schema.ts
@@ -0,0 +1,72 @@
+import { Pool, QueryResult } from "pg";
+
+type ColumnInfo = {
+  name: string;
+  type: string;
+  nullable: boolean;
+};
+
+type TableSchema = {
+  columns: Record<string, ColumnInfo>;
+};
+
+type Schema = Record<string, TableSchema>;
+
+let cachedSchema: Schema | null = null;
+
+export async function loadSchema(pool: Pool): Promise<Schema> {
+  if (cachedSchema) return cachedSchema;
+
+  const result = await pool.query(`
+    SELECT
+      t.table_name,
+      c.column_name,
+      c.data_type,
+      c.is_nullable
+    FROM
+      information_schema.tables t
+      JOIN information_schema.columns c ON t.table_schema = c.table_schema AND t.table_name = c.table_name
+    WHERE
+      t.table_schema = 'public'
+    ORDER BY
+      t.table_name, c.ordinal_position
+  `);
+
+  const schema: Schema = {};
+  for (const row of result.rows) {
+    const tableName = row.table_name;
+    const columnName = row.column_name;
+
+    if (!schema[tableName]) {
+      schema[tableName] = { columns: {} };
+    }
+
+    schema[tableName].columns[columnName] = {
+      name: columnName,
+      type: row.data_type,
+      nullable: row.is_nullable === "YES",
+    };
+  }
+
+  cachedSchema = schema;
+  return schema;
+}
+
+export function validateColumns(
+  tableName: string,
+  selectedColumns: string[],
+  schema: Schema,
+): void {
+  const tableSchema = schema[tableName];
+  if (!tableSchema) {
+    throw new Error(`Table "${tableName}" not found in schema`);
+  }
+
+  for (const col of selectedColumns) {
+    if (!tableSchema.columns[col]) {
+      throw new Error(
+        `Column "${col}" not found in table "${tableName}". Available columns: ${Object.keys(tableSchema.columns).join(", ")}`,
+      );
+    }
+  }
+}
diff --git a/src/db/typed-query.ts b/src/db/typed-query.ts
