+++ b/src/db/typed-query.ts
@@ -0,0 +1,55 @@
+import { Pool, QueryResult } from "pg";
+import { loadSchema, validateColumns } from "./schema.ts";
+
+type TypeMap = {
+  "character varying": string;
+  text: string;
+  integer: number;
+  bigint: number;
+  boolean: boolean;
+  timestamp: Date;
+  "timestamp without time zone": Date;
+  date: Date;
+  "double precision": number;
+  uuid: string;
+  json: unknown;
+  jsonb: unknown;
+};
+
+type SqlType = keyof TypeMap;
+
+type RowType<T extends Record<string, SqlType>> = {
+  [K in keyof T]: T[K] extends SqlType ? TypeMap[T[K]] : never;
+};
+
+type QueryOptions = {
+  schema: Awaited<ReturnType<typeof loadSchema>>;
+};
+
+export async function typedQuery<T extends Record<string, SqlType>>(
+  pool: Pool,
+  columnDefs: T,
+  sql: string,
+  params: unknown[],
+  options: QueryOptions,
+): Promise<RowType<T>[]> {
+  const columns = Object.keys(columnDefs);
+  const tableName = extractTableName(sql);
+
+  if (tableName) {
+    validateColumns(tableName, columns, options.schema);
+  }
+
+  const result = await pool.query(sql, params);
+  return result.rows as RowType<T>[];
+}
+
+function extractTableName(sql: string): string | null {
+  const fromMatch = sql.match(/FROM\s+(\w+)/i);
+  if (fromMatch) return fromMatch[1];
+
+  const insertMatch = sql.match(/INSERT\s+INTO\s+(\w+)/i);
+  if (insertMatch) return insertMatch[1];
+
+  return null;
+}
